<?php
$support=$researchEvidence['supporting_materials']??null;
$materialLabels=['sources'=>'Sources','inputs'=>'Inputs and original data','units'=>'Units and conversions','formulas'=>'Formulas','code'=>'Code and tests','software'=>'Software and versions','methods'=>'Methods','assumptions'=>'Assumptions','outputs'=>'Outputs','tables'=>'Data tables','intermediate_results'=>'Intermediate work','failed_approaches'=>'Failed approaches'];
$materialReferenceLabel=static function(string $ref): string {
 $direct=['body'=>'Full authored result','methodology'=>'Investigation methods','sources'=>'Sources and search record','limitations'=>'Limitations','next_action'=>'Proposed next use','evidence.sources'=>'Complete source registry'];if(isset($direct[$ref]))return $direct[$ref];
 if(preg_match('~^supporting\.files/([^/]+)$~D',$ref,$m))return 'Retained supporting file '.$m[1];
 if(preg_match('~^evidence\.(sources|claims|datasets|artifacts|calculations|derivations|tool_builds)/([^/]+)(?:/(files|inputs|outputs)/([^/]+))?$~D',$ref,$m)){$kind=['sources'=>'Source','claims'=>'Claim','datasets'=>'Dataset','artifacts'=>'Visual aid','calculations'=>'Calculation','derivations'=>'Worked arithmetic','tool_builds'=>'Research tool'][$m[1]];$label=$kind.' '.$m[2];if(isset($m[3]))$label.=' · '.['files'=>'file','inputs'=>'input','outputs'=>'output'][$m[3]].' '.$m[4];return $label;}
 return 'Retained material';
};
?>
<section id="supporting-materials"><h2>Supporting materials</h2>
<?php if(!$support): ?><p>Historical record: no structured supporting-material inventory was collected. Completeness has not been inferred.</p>
<?php else: ?><p>Work performed: <?=e(str_replace('_',' ',$support['work_performed']))?>. Materials and access declarations require independent review.</p>
<?php foreach($support['items'] as $material): ?><article class="ledger-entry"><h3><?=e($materialLabels[$material['category']]??ucwords(str_replace('_',' ',$material['category'])))?> · <?=e(str_replace('_',' ',$material['status']))?></h3><?=prose($material['details'])?><?php if($material['access_instructions']): ?><p><strong>Access and reproduction:</strong> <?=e($material['access_instructions'])?></p><?php endif ?><?php if($material['refs']): ?><ul class="material-references"><?php foreach($material['refs'] as $ref): ?><li><strong><?=e($materialReferenceLabel($ref))?></strong><details class="material-reference"><summary>Exact audit reference</summary><code><?=e($ref)?></code></details></li><?php endforeach ?></ul><?php endif ?></article><?php endforeach ?>
<?php if($support['files']): ?><h3>Retained supporting files</h3><?php foreach($support['files'] as $file): ?><article class="supporting-file"><h4 id="supporting-file-<?=e($file['id'])?>"><?=e($file['name'])?></h4><p class="fine">Contributor’s rights and redistribution statement:</p><?=prose($file['rights'])?><?php if($admission==='accepted'): try{rs_read($r['id'],$result['id']); ?><div class="actions"><a class="button secondary" aria-describedby="supporting-file-<?=e($file['id'])?>" href="<?=e($base)?>/results/<?=e($result['id'])?>/resources/files/<?=e($file['id'])?>">Download inert text</a></div><?php }catch(HttpError){} endif ?></article><?php endforeach;endif ?>
<?php endif ?>
<?php foreach($researchEvidence['material_reviews']??[] as $audit): ?><article class="task-brief"><h3>Independent material audit · <?=e($audit['verdict'])?></h3><a href="<?=e($base)?>/results/<?=e($audit['result_id'])?>#supporting-materials">Audited result</a><?=prose($audit['reason'])?><p>Inspected materials:</p><ul class="material-references"><?php foreach($audit['checked_refs'] as $ref): ?><li><strong><?=e($materialReferenceLabel($ref))?></strong><details class="material-reference"><summary>Exact audit reference</summary><code><?=e($ref)?></code></details></li><?php endforeach ?></ul></article><?php endforeach ?>
</section>
